## Why This Is Asked

Tests a beginner's ability to design a practical, auditable maintenance workflow using familiar AWS services with least-privilege access.

## Key Concepts

- AWS Systems Manager Run Command
- IAM roles with trust relationships and least privilege
- CloudWatch Logs and CloudTrail for audit trails
- AWS SSO integration for role assumption
- Minimal IaC (Terraform) to create roles and SSM associations

## Code Example

```terraform
# Terraform snippet creating cross-account SAPOperator role and IAM policy
provider "aws" { region = "us-east-1" }

# Role
resource "aws_iam_role" "sap_operator" {
  name = "SAPOperator"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { AWS = "arn:aws:iam::ACCOUNT_ID:saml-provider/AWS_SSO" },
      Action = "sts:AssumeRole"
    }]
  })
}

# Policy
resource "aws_iam_policy" "sap_operator_policy" {
  name = "SAPOperatorPolicy"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      { Effect = "Allow", Action = ["ssm:SendCommand","ssm:ListCommands","ssm:DescribeInstanceInformation"], Resource = "*" },
      { Effect = "Allow", Action = ["logs:CreateLogGroup","logs:CreateLogStream","logs:PutLogEvents"], Resource = "*" }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach" {
  role       = aws_iam_role.sap_operator.name
  policy_arn = aws_iam_policy.sap_operator_policy.arn
}
```

```terraform
# SSM association to run healthcheck on SAP EC2
data "aws_ssm_document" "run_shell" { name = "AWS-RunShellScript" }

resource "aws_ssm_association" "healthcheck" {
  name            = data.aws_ssm_document.run_shell.name
  instance_id     = "<SAP_EC2_INSTANCE_ID>"
  parameters = {
    commands = ["bash /usr/local/bin/healthcheck.sh"]
  }
}
```

